package com.edufun.portal.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="tutor_assignments") public class TutorAssignment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long tutorId; private Long studentId; private String status="ACTIVE"; private String notes; private LocalDateTime assignedAt=LocalDateTime.now(); public Long getId(){return id;} public Long getTutorId(){return tutorId;} public void setTutorId(Long v){tutorId=v;} public Long getStudentId(){return studentId;} public void setStudentId(Long v){studentId=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} public LocalDateTime getAssignedAt(){return assignedAt;} public void setAssignedAt(LocalDateTime v){assignedAt=v;} }
